<?php
declare(strict_types=1);
foreach(['core','business','audit','product-import'] as $file)require __DIR__."/$file.php";
function productCheck(bool $pass,string $message): void {if(!$pass)throw new RuntimeException($message);}
$c=config();$db=db($c);
$sample=['line'=>2,'product'=>'Netflix','purchase_source'=>'Đại lý A','customer_name'=>'Đặng Thị Hồng','email'=>'Guest@Example.com','contact'=>'Zalo','plan_months'=>'3 tháng','joined_at'=>'31/01/2026','expires_at'=>'','payment_status'=>'Đã thanh toán','amount'=>'165.000 đ','note'=>'Ghi chú'];
$normalized=productImportNormalize($sample);productCheck($normalized['purchase_source']==='Đại lý A'&&$normalized['amount']===165000&&$normalized['joined_at']==='2026-01-31'&&$normalized['expires_at']==='2026-04-30'&&$normalized['payment_status']==='paid'&&$normalized['email']==='guest@example.com','date/money/Vietnamese normalization');
productCheck(productImportNormalize([...$sample,'plan_months'=>'1 năm','amount'=>'1,000,000 VND'])['plan_months']===12,'year plan normalization');
foreach(['plan_months'=>['-1','1.5','1/2','121 tháng'],'joined_at'=>['31/02/2026','01/02','0000-01-01'],'amount'=>['165,00','1.234,000','-500','1e5','1000000001']] as $field=>$values)foreach($values as $value){$rejected=false;try{productImportNormalize([...$sample,$field=>$value]);}catch(FamilyError $e){$rejected=$e->status===400;}productCheck($rejected,'reject malformed '.$field);}
$duplicate=[...$sample,'line'=>3];$bad=[...$sample,'line'=>4,'joined_at'=>'31/02/2026'];$before=(int)one($db,'SELECT COUNT(*) AS n FROM other_purchases')['n'];$preview=productImportPreview($db,['items'=>[$sample,$duplicate,$bad]]);productCheck(!$preview['valid']&&$preview['errors'][0]['line']===4&&$preview['added']===1&&$preview['skipped']===1,'preview row errors and duplicates');productCheck((int)one($db,'SELECT COUNT(*) AS n FROM other_purchases')['n']===$before,'preview read only');
$preview=productImportPreview($db,['items'=>[$sample,$duplicate]]);$request=['items'=>[$sample,$duplicate],'preview_token'=>$preview['preview_token']];productCheck(productImportConfirm($db,$request)['added']===1,'commit adds one');productCheck(productImportConfirm($db,$request)['added']===0,'retry does not duplicate');productCheck((int)one($db,'SELECT COUNT(*) AS n FROM other_purchases')['n']===$before+1,'one inserted');
productCheck(productImportPreview($db,['items'=>[[...$sample,'purchase_source'=>'Đại lý B']]])['added']===1,'different provider is not an exact duplicate');
$second=[...$sample,'line'=>5,'email'=>'second@example.com'];$preview=productImportPreview($db,['items'=>[$sample,$second]]);q($db,'UPDATE other_purchases SET note=? WHERE email=?',['Changed separately','guest@example.com']);$rejected=false;try{productImportConfirm($db,['items'=>[$sample,$second],'preview_token'=>$preview['preview_token']]);}catch(FamilyError $e){$rejected=$e->status===409;}productCheck($rejected,'stale preview rejected');productCheck((int)one($db,'SELECT COUNT(*) AS n FROM other_purchases')['n']===$before+1,'stale no mutation');
$first=[...$sample,'line'=>2,'email'=>'atomic@example.com'];$failure=[...$sample,'line'=>3,'email'=>'failure@example.com','product'=>'Failure product'];$preview=productImportPreview($db,['items'=>[$first,$failure]]);$logs=(int)one($db,'SELECT COUNT(*) AS n FROM logs')['n'];
$db->exec("CREATE TRIGGER reject_product_insert BEFORE INSERT ON other_purchases FOR EACH ROW BEGIN IF NEW.product='Failure product' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Injected test failure'; END IF; END");
$rejected=false;try{productImportConfirm($db,['items'=>[$first,$failure],'preview_token'=>$preview['preview_token']]);}catch(PDOException $e){$rejected=true;}$db->exec('DROP TRIGGER reject_product_insert');productCheck($rejected,'injected insert rejected');productCheck((int)one($db,'SELECT COUNT(*) AS n FROM other_purchases')['n']===$before+1,'all rows rolled back');productCheck((int)one($db,'SELECT COUNT(*) AS n FROM logs')['n']===$logs,'logs rolled back');
echo "Product Sheet import checks passed\n";
